	m := feed(t, New(cfg), testutil.Resize(width, 20))
	s := session("id-a000000-0000", "/srv/pa", 0)
	s.Parent = "/p/a.jsonl"
	m = loaded(t, m, s)
	m, _ = opened(t, m, "right")
	return answer(t, m, u)
}

